"use strict";

/*
 * cnotes.h documentation viewer.
 * Loads doc.json (generated by `./nob doc`) and renders a searchable API reference into docs.html.
 *
 * Pages are selected by the URL hash:
 *   #            index of all symbols, grouped by module
 *   #<symbol>    page of a single symbol
 * While the search box is not empty, the page shows the ranked search results instead.
 */
(function () {
    const DATA_URL = "doc.json";
    const TITLE = "cnotes.h";

    // How each tag kind from nob.c is displayed.
    // "section" tags get their own titled section, "badge" tags are shown next to the symbol name,
    // everything else becomes a callout.
    const TAGS = {
        MEMBER:    { label: "Members",    kind: "section" },
        PARAM:     { label: "Parameters", kind: "section" },
        RETURNS:   { label: "Returns",    kind: "section" },
        SINCE:     { label: "Since",      kind: "badge" },
        NOTE:      { label: "Note",      kind: "callout", tone: "note" },
        AI:        { label: "AI",        kind: "callout", tone: "note" },
        IMPORTANT: { label: "Important", kind: "callout", tone: "important" },
        TODO:      { label: "Todo",      kind: "callout", tone: "todo" },
        FIXME:     { label: "Fixme",     kind: "callout", tone: "todo" },
        LEAK:      { label: "Leak",      kind: "callout", tone: "warn" },
        TEMPORARY: { label: "Temporary", kind: "callout", tone: "warn" },
    };
    const SECTION_ORDER = ["MEMBER", "PARAM", "RETURNS"];

    // Flags from nob.c, shown as badges.
    const FLAGS = {
        "--gnu": "GNU extension",
    };

    const C_KEYWORDS = new Set([
        "const", "volatile", "restrict", "static", "inline", "extern",
        "struct", "union", "enum", "unsigned", "signed", "typedef", "sizeof",
        "if", "else", "for", "while", "do", "switch", "case", "default",
        "break", "continue", "return", "goto",
    ]);
    const C_TYPES = new Set([
        "void", "char", "short", "int", "long", "float", "double", "bool", "_Bool",
        "size_t", "ssize_t", "ptrdiff_t", "intptr_t", "uintptr_t", "va_list", "FILE",
    ]);

    const dom = {
        search: document.getElementById("search"),
        nav:    document.getElementById("nav"),
        page:   document.getElementById("page"),
    };

    const state = {
        entries: [],          // All entries in header order.
        modules: [],          // { name, entries }
        byId:    new Map(),   // Hash id -> entry.
        results: [],          // Entries matching the current search, best first.
        active:  null,        // Entry whose page is shown.
        depth:   0,           // How many pages of this tab's history are before the current one.
    };


    /* ---------- Helpers ---------- */

    const HTML_ESCAPES = { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" };

    function escapeHtml(text) {
        return String(text).replace(/[&<>"']/g, (c) => HTML_ESCAPES[c]);
    }

    function asString(value) {
        return typeof value === "string" ? value : "";
    }

    function isTypingTarget(target) {
        return target instanceof HTMLElement &&
            (target.isContentEditable || /^(INPUT|TEXTAREA|SELECT)$/.test(target.tagName));
    }

    function currentHash() {
        return decodeURIComponent(location.hash.slice(1));
    }


    /* ---------- Data ---------- */

    // Splits `text` on commas that are not nested in (), [] or {}.
    function splitTopLevel(text) {
        const parts = [];
        let depth = 0;
        let start = 0;
        for (let i = 0; i < text.length; i++) {
            const c = text[i];
            if ("([{".includes(c)) depth++;
            else if (")]}".includes(c)) depth--;
            else if (c === "," && depth === 0) {
                parts.push(text.slice(start, i));
                start = i + 1;
            }
        }
        parts.push(text.slice(start));
        return parts.map((p) => p.trim()).filter(Boolean);
    }

    function tidyType(type) {
        return type.replace(/\s+/g, " ").replace(/\s+\*/g, " *").trim();
    }

    // Splits a single declaration, like `int *x` or `void (*f)(int)`, into its name and type.
    // Returns null if it declares no name.
    function splitDeclaration(text) {
        // Function pointer `ret (*name)(args)`, otherwise the last identifier, before any `[...]` or bit-field width.
        const fnPtr = /\(\s*\*\s*([A-Za-z_]\w*)\s*\)/.exec(text);
        const plain = /([A-Za-z_]\w*)\s*(\[[^\]]*\]\s*)*(:\s*\w+\s*)?$/.exec(text);
        const match = fnPtr || plain;
        if (!match || C_KEYWORDS.has(match[1]) || C_TYPES.has(match[1])) return null;

        const name = match[1];
        const type = tidyType(fnPtr
            ? text.slice(0, fnPtr.index) + "(*)" + text.slice(fnPtr.index + fnPtr[0].length)
            : text.slice(0, plain.index) + text.slice(plain.index + name.length));
        return type ? { name, type } : null;
    }

    // Reads return type and named parameters out of a function, function typedef or function-like macro.
    // Returns { returnType, params: Map name -> type }, empty if `decl` is none of those.
    function parseDecl(decl, symbol) {
        const result = { returnType: "", params: new Map() };

        // Name is followed by the parameter list, function typedefs close their `(name)` or `(*name)` first.
        const head = new RegExp(`\\b${symbol}\\s*\\)?\\s*\\(`).exec(decl);
        if (!head) return result;

        result.returnType = tidyType(decl.slice(0, head.index)
            .replace(/\b(CNDEF|static|inline|extern|typedef)\b/g, "")
            .replace(/\(\s*\*?\s*$/, ""));

        // Matching ")" of the parameter list.
        let depth = 0;
        let end = -1;
        const open = head.index + head[0].length - 1;
        for (let i = open; i < decl.length; i++) {
            if (decl[i] === "(") depth++;
            else if (decl[i] === ")" && --depth === 0) { end = i; break; }
        }
        if (end === -1) return result;

        for (const param of splitTopLevel(decl.slice(open + 1, end))) {
            const field = splitDeclaration(param);
            if (field) result.params.set(field.name, field.type);
        }
        return result;
    }

    // Reads members of a struct or union declaration into `members`, Map name -> type.
    // Members of anonymous nested structs and unions belong to the outer one, named nested ones are shown collapsed.
    function parseMembers(decl, members = new Map()) {
        const open = decl.indexOf("{");
        const close = decl.lastIndexOf("}");
        if (open === -1 || close < open) return members;

        // Preprocessor lines and comments are not members.
        const body = decl.slice(open + 1, close)
            .replace(/\/\*[\s\S]*?\*\//g, "")
            .replace(/\/\/.*$/gm, "")
            .replace(/^\s*#.*$/gm, "");

        let depth = 0;
        let start = 0;
        for (let i = 0; i < body.length; i++) {
            const c = body[i];
            if (c === "{") depth++;
            else if (c === "}") depth--;
            if (c !== ";" || depth !== 0) continue;

            const member = body.slice(start, i).trim();
            start = i + 1;

            if (member.includes("{")) {
                const after = member.slice(member.lastIndexOf("}") + 1).trim();
                const keyword = /^\s*(struct|union)\b/.exec(member);
                if (!after) parseMembers(member, members);
                else if (/^[A-Za-z_]\w*$/.test(after)) members.set(after, `${keyword ? keyword[1] : "struct"} { … }`);
                continue;
            }

            // `int a, *b` declares several members of the same base type.
            const [first, ...rest] = splitTopLevel(member);
            const field = first && splitDeclaration(first);
            if (!field) continue;
            members.set(field.name, field.type);

            const base = field.type.replace(/[\s*]+$/, "");
            for (const other of rest) {
                const extra = splitDeclaration(`${base} ${other}`);
                if (extra) members.set(extra.name, extra.type);
            }
        }
        return members;
    }

    // Turns raw JSON into a well-formed entry, or null if it is unusable.
    function normalizeEntry(raw, index) {
        if (!raw || typeof raw !== "object") return null;

        const symbol = asString(raw.symbol).trim();
        if (!symbol) return null;

        const tags = (Array.isArray(raw.tags) ? raw.tags : [])
            .filter((tag) => tag && typeof tag === "object")
            .map((tag) => ({
                kind:      asString(tag.kind).toUpperCase() || "NOTE",
                name:      asString(tag.name).trim(),
                modifiers: (Array.isArray(tag.modifiers) ? tag.modifiers : []).map(asString).filter(Boolean),
                text:      asString(tag.text).trim(),
            }))
            .filter((tag) => tag.text || tag.name);

        const flags = (Array.isArray(raw.flags) ? raw.flags : []).map(asString).filter(Boolean);

        const entry = {
            index,
            symbol,
            name:        symbol.replace(/^cn_/, ""),
            decl:        asString(raw.decl).trim(),
            summary:     asString(raw.summary).trim(),
            description: asString(raw.description).trim(),
            tags,
            flags,
            kind:        asString(raw.kind) || "function",
            module:      asString(raw.module).trim(),
        };

        // Types of parameters and members, shown next to their names. Return type comes from functions and function typedefs.
        entry.sig = parseDecl(entry.decl, symbol);
        if (entry.kind !== "function" && entry.kind !== "typedef") entry.sig.returnType = "";
        if (entry.kind === "struct" || entry.kind === "union") parseMembers(entry.decl, entry.sig.params);

        entry.haystack = {
            symbol:  entry.symbol.toLowerCase(),
            name:    entry.name.toLowerCase(),
            decl:    entry.decl.toLowerCase(),
            summary: entry.summary.toLowerCase(),
            rest:    (entry.description + "\n" + tags.map((t) => (t.name ? t.name + " " : "") + t.text).join("\n")).toLowerCase(),
        };
        return entry;
    }

    function loadEntries(data) {
        if (!Array.isArray(data)) throw new Error("doc.json must contain a JSON array of entries.");

        const usedIds = new Set();
        for (const raw of data) {
            const entry = normalizeEntry(raw, state.entries.length);
            if (!entry) continue;

            // Ids must be unique even if a symbol is documented twice.
            let id = entry.symbol;
            for (let n = 2; usedIds.has(id); n++) id = `${entry.symbol}-${n}`;
            usedIds.add(id);
            entry.id = id;

            state.entries.push(entry);
            state.byId.set(id, entry);
        }

        // Group by module, the "SECTION:" of cnotes.h each entry is declared in, keeping header order.
        const byModule = new Map();
        for (const e of state.entries) {
            if (!e.module) e.module = "misc";
            if (!byModule.has(e.module)) byModule.set(e.module, { name: e.module, entries: [] });
            byModule.get(e.module).entries.push(e);
        }
        state.modules = [...byModule.values()];
    }


    /* ---------- Rendering: text ---------- */

    // Wraps every occurrence of the search tokens in <mark>. Returns safe HTML.
    function highlight(text, tokens) {
        if (!text || tokens.length === 0) return escapeHtml(text);

        const lower = text.toLowerCase();
        const ranges = [];
        for (const token of tokens) {
            for (let i = lower.indexOf(token); i !== -1; i = lower.indexOf(token, i + token.length)) {
                ranges.push([i, i + token.length]);
            }
        }
        if (ranges.length === 0) return escapeHtml(text);

        ranges.sort((a, b) => a[0] - b[0]);
        let html = "";
        let cursor = 0;
        for (const [start, end] of ranges) {
            if (end <= cursor) continue;
            const from = Math.max(start, cursor);
            html += escapeHtml(text.slice(cursor, from));
            html += `<mark>${escapeHtml(text.slice(from, end))}</mark>`;
            cursor = end;
        }
        return html + escapeHtml(text.slice(cursor));
    }

    // Entry referenced by `name` or `name()`, null if it is not documented.
    function lookupRef(code) {
        return state.byId.get(code.trim().replace(/\(\s*\)$/, "")) || null;
    }

    // Inline text: `code` links to the entry it names, otherwise it is shown as highlighted code.
    // ```code``` on a single line counts as inline code too.
    function renderInline(text) {
        return text.split(/(```[^\n]+?```|`[^`\n]+`)/).map((part) => {
            if (part.length > 2 && part.startsWith("`") && part.endsWith("`")) {
                const ticks = part.startsWith("```") && part.length > 6 ? 3 : 1;
                const code = part.slice(ticks, -ticks);
                const target = lookupRef(code);
                if (target) return `<a class="xref" href="#${escapeHtml(target.id)}"><code>${escapeHtml(code)}</code></a>`;
                return `<code>${highlightC(code)}</code>`;
            }
            return escapeHtml(part);
        }).join("");
    }

    // Removes indentation common to all non-blank lines.
    function dedent(code) {
        const lines = code.split("\n");
        const indents = lines.filter((l) => l.trim()).map((l) => l.match(/^[ \t]*/)[0].length);
        const cut = indents.length ? Math.min(...indents) : 0;
        return lines.map((l) => l.slice(cut)).join("\n");
    }

    // Content of ```lang ... ```. Only "c" gets syntax colors, anything else (grammar rules, output) stays plain.
    function renderCodeBlock(raw) {
        let lang = "";
        let code = raw;
        const header = /^[ \t]*([A-Za-z0-9_+-]+)[ \t]*\n/.exec(raw);
        if (header) {
            lang = header[1].toLowerCase();
            code = raw.slice(header[0].length);
        }

        code = dedent(code.replace(/^[ \t]*\n/, "")).trimEnd();
        if (!code) return "";

        const body = lang === "c" ? highlightC(code) : escapeHtml(code);
        return `<pre class="code-block"><code>${body}</code></pre>`;
    }

    // Joins wrapped lines of a paragraph back into one line.
    function unwrap(text) {
        return text.split("\n").map((line) => line.trim()).filter(Boolean).join(" ");
    }

    function renderParagraphs(text) {
        return text.split(/\n[ \t]*\n/)
            .map(unwrap)
            .filter(Boolean)
            .map((paragraph) => `<p>${renderInline(paragraph)}</p>`)
            .join("");
    }

    // Same rule as the parser in nob.c: a line starting with ``` opens or closes a fence,
    // unless it closes on the same line too (```one-liner```), which is inline code.
    function isFenceLine(line) {
        const trimmed = line.trim();
        return trimmed.startsWith("```") && !trimmed.slice(3).includes("```");
    }

    // Block text, markdown style: ``` fences become code blocks kept verbatim,
    // the rest is split into paragraphs on blank lines, single "\n" is just a wrapped line.
    // An unclosed fence runs to the end of the text.
    function renderBlocks(text) {
        let html = "";
        let prose = [];
        let code = null; // Lines of the open fence, including its "```lang" header.

        for (const line of text.split("\n")) {
            if (code === null) {
                if (isFenceLine(line)) {
                    html += renderParagraphs(prose.join("\n"));
                    prose = [];
                    code = [line.trim().slice(3)];
                } else {
                    prose.push(line);
                }
            } else if (isFenceLine(line)) {
                html += renderCodeBlock(code.join("\n"));
                code = null;
            } else {
                code.push(line);
            }
        }

        if (code !== null) html += renderCodeBlock(code.join("\n"));
        return html + renderParagraphs(prose.join("\n"));
    }

    // Syntax colors for C. Identifiers naming another documented symbol become links to its page.
    function highlightC(code, symbol) {
        const tokenRe = /([A-Za-z_]\w*)|(\s+)|([^\sA-Za-z_]+)/g;
        let html = "";
        let match;
        while ((match = tokenRe.exec(code)) !== null) {
            const [token, ident, space] = match;
            if (space) {
                html += space;
            } else if (ident) {
                if (ident !== symbol && state.byId.has(ident)) {
                    html += `<a class="xref tok-fn" href="#${escapeHtml(ident)}">${escapeHtml(token)}</a>`;
                    continue;
                }
                let cls = "";
                if (ident === symbol)                                   cls = "tok-fn";
                else if (C_KEYWORDS.has(ident))                         cls = "tok-kw";
                else if (C_TYPES.has(ident) || /^[A-Z]/.test(ident) || /_t$/.test(ident)) cls = "tok-type";
                html += cls ? `<span class="${cls}">${escapeHtml(token)}</span>` : escapeHtml(token);
            } else {
                html += `<span class="tok-punct">${escapeHtml(token)}</span>`;
            }
        }
        return html;
    }


    /* ---------- Pages ---------- */

    // Modifiers of a PARAM or MEMBER, plain "in" is the default and is not shown.
    function modifierBadges(modifiers) {
        const shown = modifiers.includes("out") ? modifiers : modifiers.filter((m) => m !== "in");
        return shown.map((m) => `<span class="pmod">${escapeHtml(m)}</span>`).join("");
    }

    // Row of a section table: name with its modifiers, type and description.
    function sectionRow(tag, entry) {
        if (tag.kind === "RETURNS") {
            const type = entry.sig.returnType === "void" ? "" : entry.sig.returnType;
            return { name: "", modifiers: [], type, text: tag.text };
        }
        return { name: tag.name, modifiers: tag.modifiers, type: entry.sig.params.get(tag.name) || "", text: tag.text };
    }

    // Every section is one table, its rows share the columns, so descriptions line up no matter the name lengths.
    // Name and type columns are only there if at least one row has them.
    function renderSection(label, rows) {
        const hasName = rows.some((r) => r.name);
        const hasType = rows.some((r) => r.type);
        const cls = ["fields", hasName && "has-name", hasType && "has-type"].filter(Boolean).join(" ");

        const cells = (r) =>
            (hasName ? `<div class="field-name"><span class="pname">${escapeHtml(r.name)}</span>${modifierBadges(r.modifiers)}</div>` : "") +
            (hasType ? `<div class="field-type">${r.type ? `<code>${highlightC(r.type)}</code>` : ""}</div>` : "") +
            `<div class="field-text">${renderBlocks(r.text)}</div>`;

        return `<section class="section"><h2 class="eyebrow">${escapeHtml(label)}</h2>` +
            `<div class="${cls}">${rows.map((r) => `<div class="field">${cells(r)}</div>`).join("")}</div></section>`;
    }

    function renderSections(entry) {
        return SECTION_ORDER.map((kind) => {
            const tags = entry.tags.filter((t) => t.kind === kind);
            return tags.length ? renderSection(TAGS[kind].label, tags.map((t) => sectionRow(t, entry))) : "";
        }).join("");
    }

    function renderCallouts(tags) {
        return tags.filter((t) => !TAGS[t.kind] || TAGS[t.kind].kind === "callout").map((t) => {
            const info = TAGS[t.kind] || { label: t.kind, tone: "note" };
            return `<aside class="callout callout-${info.tone}">` +
                `<div class="callout-label">${escapeHtml(info.label)}</div>${renderBlocks(t.text)}</aside>`;
        }).join("");
    }

    function renderBadges(entry) {
        const badges = [`<span class="badge">${escapeHtml(entry.kind)}</span>`];
        for (const t of entry.tags.filter((t) => t.kind === "SINCE")) {
            badges.push(`<span class="badge">Since <b>${escapeHtml(t.text)}</b></span>`);
        }
        for (const flag of entry.flags) {
            badges.push(`<span class="badge">${escapeHtml(FLAGS[flag] || flag.replace(/^-+/, ""))}</span>`);
        }
        return `<div class="badges">${badges.join("")}</div>`;
    }

    function symbolPage(entry) {
        const signature = entry.decl || entry.symbol;
        return `
            <p class="crumbs">${backButton()}<span><a href="#">API Reference</a> / ${escapeHtml(entry.module)}</span></p>
            <div class="symbol-head">
                <h1 class="symbol-name">${escapeHtml(entry.symbol)}</h1>
                ${renderBadges(entry)}
            </div>
            <div class="signature">
                <pre><code>${highlightC(signature, entry.symbol)}</code></pre>
                <button class="copy" type="button" data-copy="${escapeHtml(signature)}">Copy</button>
            </div>
            <div class="entry">
                <div class="prose">
                    ${entry.summary
                        ? `<p class="summary">${renderInline(unwrap(entry.summary))}</p>`
                        : `<p class="summary missing">No summary.</p>`}
                    ${entry.description ? renderBlocks(entry.description) : ""}
                </div>
                ${renderSections(entry)}
                ${renderCallouts(entry.tags)}
            </div>
        `;
    }

    // Table of symbol names and summaries.
    function symbolTable(entries, tokens) {
        return `<table class="index">` + entries.map((e) => `
            <tr>
                <td><a href="#${escapeHtml(e.id)}">${highlight(e.symbol, tokens)}</a></td>
                <td>${highlight(unwrap(e.summary), tokens)}</td>
            </tr>`).join("") + `</table>`;
    }

    // Arrow back to the previously viewed page, only once there is one.
    function backButton() {
        if (state.depth < 1) return "";
        return `<button class="back" type="button" title="Back to the previous page">← Back</button>`;
    }

    function indexPage() {
        const back = backButton();
        return (back ? `<p class="crumbs">${back}</p>` : "") + `<h1>API Reference</h1>` + state.modules.map((mod) =>
            `<h2 class="eyebrow">${escapeHtml(mod.name)}</h2>${symbolTable(mod.entries, [])}`
        ).join("");
    }

    function resultsPage(tokens) {
        if (state.results.length === 0) {
            return `<p class="notice">No symbols match <strong>${escapeHtml(dom.search.value.trim())}</strong>.</p>`;
        }
        return symbolTable(state.results, tokens);
    }

    function buildNav() {
        dom.nav.innerHTML = state.modules.map((mod) => `
            <div class="nav-module eyebrow">${escapeHtml(mod.name)}</div>
            <ul class="nav-list">${mod.entries.map((e) =>
                `<li><a href="#${escapeHtml(e.id)}" title="${escapeHtml(e.symbol)}">${escapeHtml(e.symbol)}</a></li>`
            ).join("")}</ul>
        `).join("");

        const titles = dom.nav.querySelectorAll(".nav-module");
        state.modules.forEach((mod, i) => {
            mod.navTitle = titles[i];
            const links = mod.navTitle.nextElementSibling.querySelectorAll("a");
            mod.entries.forEach((e, j) => { e.navLink = links[j]; });
        });
    }

    // Sidebar shows only the entries matching the search.
    function filterNav(visible) {
        for (const mod of state.modules) {
            let shown = false;
            for (const e of mod.entries) {
                const isShown = !visible || visible.has(e);
                e.navLink.parentElement.hidden = !isShown;
                shown = shown || isShown;
            }
            mod.navTitle.hidden = !shown;
            mod.navTitle.nextElementSibling.hidden = !shown;
        }
    }

    function setActive(entry) {
        if (state.active) state.active.navLink.classList.remove("active");
        state.active = entry;
        if (!entry) return;

        const link = entry.navLink;
        link.classList.add("active");

        // Keep the active link in view inside the sidebar.
        const nav = dom.nav;
        const top = link.offsetTop - nav.offsetTop;
        if (top < nav.scrollTop || top > nav.scrollTop + nav.clientHeight - 40) {
            nav.scrollTop = top - nav.clientHeight / 3;
        }
    }


    /* ---------- Search ---------- */

    function tokenize(query) {
        return query.toLowerCase().split(/\s+/).filter(Boolean);
    }

    // Every token must match somewhere; matches in the name weigh the most.
    function score(entry, tokens) {
        const h = entry.haystack;
        let total = 0;
        for (const t of tokens) {
            if (h.symbol === t || h.name === t)                      total += 100;
            else if (h.symbol.startsWith(t) || h.name.startsWith(t)) total += 60;
            else if (h.symbol.includes(t))                           total += 40;
            else if (h.decl.includes(t))                             total += 15;
            else if (h.summary.includes(t))                          total += 10;
            else if (h.rest.includes(t))                             total += 5;
            else return 0;
        }
        return total;
    }

    function search(tokens) {
        state.results = state.entries
            .map((e) => ({ e, s: score(e, tokens) }))
            .filter((r) => r.s > 0)
            .sort((a, b) => b.s - a.s || a.e.index - b.e.index)
            .map((r) => r.e);
    }


    /* ---------- Router ---------- */

    function render() {
        const tokens = tokenize(dom.search.value);
        const entry = state.byId.get(currentHash()) || null;

        if (tokens.length) {
            search(tokens);
            filterNav(new Set(state.results));
            dom.page.innerHTML = resultsPage(tokens);
            document.title = `Search — ${TITLE}`;
            return;
        }

        filterNav(null);
        setActive(entry);

        if (entry) {
            dom.page.innerHTML = symbolPage(entry);
            document.title = `${entry.symbol} — ${TITLE}`;
        } else if (currentHash()) {
            dom.page.innerHTML = `<p class="crumbs">${backButton()}</p><p class="notice">No symbol named <code>${escapeHtml(currentHash())}</code>. ` +
                `<a href="#">Back to index</a>.</p>`;
            document.title = TITLE;
        } else {
            dom.page.innerHTML = indexPage();
            document.title = `API Reference — ${TITLE}`;
        }
    }

    // Each history entry remembers its depth and scroll positions. A new entry has no state yet and gets
    // the depth after the previous page, entries reached by back or forward already have theirs.
    // RETURNS: Saved state of the entry, null if the page is visited for the first time.
    function updateDepth(isFirstPage) {
        const saved = history.state && typeof history.state.depth === "number" ? history.state : null;
        if (saved === null) {
            state.depth = isFirstPage ? 0 : state.depth + 1;
            history.replaceState({ depth: state.depth }, "");
        } else {
            state.depth = saved.depth;
        }
        return saved;
    }

    // Stores where the page and the sidebar are scrolled into the current history entry.
    function saveScroll() {
        history.replaceState({ depth: state.depth, page: window.scrollY, nav: dom.nav.scrollTop }, "");
    }

    let saveScrollTimer = 0;
    function saveScrollSoon() {
        clearTimeout(saveScrollTimer);
        saveScrollTimer = setTimeout(saveScroll, 150);
    }

    // Puts page and sidebar back where they were, if they were saved.
    function restoreScroll(saved) {
        if (!saved || typeof saved.page !== "number") return false;
        window.scrollTo({ top: saved.page });
        if (typeof saved.nav === "number") dom.nav.scrollTop = saved.nav;
        return true;
    }

    // Following any link leaves the search and opens the page from the top.
    // Revisited pages open where they were left, new ones from the top.
    function navigate(saved) {
        dom.search.value = "";
        render();
        if (!restoreScroll(saved)) window.scrollTo({ top: 0 });
    }


    /* ---------- Clipboard ---------- */

    function copyText(text, button) {
        const done = () => {
            button.textContent = "Copied";
            setTimeout(() => { button.textContent = "Copy"; }, 1200);
        };

        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(text).then(done, () => fallbackCopy(text) && done());
        } else if (fallbackCopy(text)) {
            done();
        }
    }

    function fallbackCopy(text) {
        const area = document.createElement("textarea");
        area.value = text;
        area.style.position = "fixed";
        area.style.opacity = "0";
        document.body.append(area);
        area.select();
        let ok = false;
        try { ok = document.execCommand("copy"); } catch (_) { ok = false; }
        area.remove();
        return ok;
    }


    /* ---------- Events ---------- */

    function bindEvents() {
        dom.search.addEventListener("input", render);

        dom.search.addEventListener("keydown", (ev) => {
            if (ev.key === "Escape") {
                if (dom.search.value) {
                    dom.search.value = "";
                    render();
                } else {
                    dom.search.blur();
                }
            } else if (ev.key === "Enter" && dom.search.value.trim() && state.results.length) {
                const first = state.results[0];
                dom.search.blur();
                if (currentHash() === first.id) navigate();
                else location.hash = first.id;
            }
        });

        document.addEventListener("keydown", (ev) => {
            const slash = ev.key === "/" && !isTypingTarget(ev.target);
            const ctrlK = (ev.ctrlKey || ev.metaKey) && ev.key.toLowerCase() === "k";
            if (slash || ctrlK) {
                ev.preventDefault();
                dom.search.focus();
                dom.search.select();
            }
        });

        document.addEventListener("click", (ev) => {
            if (!(ev.target instanceof Element)) return;

            // Scroll is saved before leaving, so going back returns to the clicked link.
            if (ev.target.closest("a, .back")) saveScroll();

            if (ev.target.closest(".back")) {
                history.back();
                return;
            }

            const copy = ev.target.closest(".copy");
            if (copy) {
                copyText(copy.dataset.copy, copy);
                return;
            }

            // A link to the current page does not fire "hashchange"; still leave the search.
            const link = ev.target.closest('a[href^="#"]');
            if (link && link.getAttribute("href") === (location.hash || "#")) {
                ev.preventDefault();
                navigate();
            }
        });

        window.addEventListener("hashchange", () => navigate(updateDepth(false)));

        // Browser would restore scroll on its own before the page is rendered, it is done after rendering instead.
        if ("scrollRestoration" in history) history.scrollRestoration = "manual";
        window.addEventListener("scroll", saveScrollSoon, { passive: true });
        dom.nav.addEventListener("scroll", saveScrollSoon, { passive: true });
    }


    /* ---------- Startup ---------- */

    function showError(error) {
        const fromFile = location.protocol === "file:";
        dom.page.innerHTML = `
            <p class="notice error"><strong>Could not load ${DATA_URL}.</strong> ${escapeHtml(error.message || String(error))}</p>
            ${fromFile
                ? `<p>Browsers block loading files from <code>file://</code> pages. Serve the folder instead:
                   <code>python3 -m http.server -d doc 8000</code> and open <code>http://localhost:8000/docs.html</code></p>`
                : `<p>Generate it with <code>./nob doc</code> and reload the page.</p>`}
        `;
    }

    async function main() {
        bindEvents();
        try {
            const response = await fetch(DATA_URL, { cache: "no-cache" });
            if (!response.ok) throw new Error(`Server responded with ${response.status} ${response.statusText}.`);
            loadEntries(await response.json());
        } catch (error) {
            showError(error);
            return;
        }

        buildNav();
        const saved = updateDepth(true);
        render();
        restoreScroll(saved); // Reloaded page opens where it was.
    }

    main();
})();
